<?php /** @var array $rows @var string $search @var string $eventPrefix @var int $total @var int $page @var int $pages @var string $basePath @var string|null $warning */ $warning=$warning??null; ?>
<?php if ($warning !== null): ?><div class="flash-error" role="alert"><strong>Audit log needs attention.</strong><p><?= e($warning) ?></p></div><?php endif; ?>
<div class="card"><div class="card-heading"><div><p class="section-kicker">Accountability</p><h2>Administrative activity</h2><p class="card-subtitle"><?= (int) $total ?> recorded event<?= $total === 1 ? '' : 's' ?>. Sensitive values are redacted before storage.</p></div><a class="btn small secondary" href="<?= e_attr($basePath) ?>/admin/audit/export">Export CSV</a></div>
  <form class="filter-bar" method="get" action="<?= e_attr($basePath) ?>/admin/audit"><div><label for="audit-search">Search event, context, or IP</label><input id="audit-search" type="search" name="q" value="<?= e_attr($search) ?>" placeholder="backup, settings, admin…"></div><div><label for="audit-event">Event family</label><select id="audit-event" name="event"><option value="">All events</option><?php foreach(['auth.'=>'Authentication','admin.'=>'Administrators','settings.'=>'Settings','modules.'=>'Modules','backup.'=>'Backups','core.'=>'Core updates','privacy.'=>'Privacy','integrations.'=>'Integrations'] as $value=>$label): ?><option value="<?= e_attr($value) ?>" <?= $eventPrefix===$value?'selected':'' ?>><?= e($label) ?></option><?php endforeach; ?></select></div><div class="button-row align-end"><button class="btn">Filter</button><?php if ($search !== '' || $eventPrefix !== ''): ?><a class="btn secondary" href="<?= e_attr($basePath) ?>/admin/audit">Clear</a><?php endif; ?></div></form>
<?php if ($rows === []): ?><div class="empty-state"><strong>No matching activity</strong><span>Administrative changes will be recorded here.</span></div><?php else: ?><div class="audit-timeline"><?php foreach ($rows as $row): $detail = json_decode((string) ($row['context'] ?? ''), true); ?><article class="audit-event"><time><strong><?= e(date('M j, Y', strtotime((string) ($row['created_at'] ?? 'now')))) ?></strong><span><?= e(date('g:i:s a', strtotime((string) ($row['created_at'] ?? 'now')))) ?></span></time><div><span class="badge neutral"><?= e(str_replace(['.', '_'], ' ', (string) ($row['event'] ?? ''))) ?></span><p><?= e(is_array($detail) && $detail!==[] ? implode(' · ', array_map(static fn ($k, $v): string => (string) $k . ': ' . (is_scalar($v) ? (string) $v : '[data]'), array_keys($detail), $detail)) : 'No additional context') ?></p><small>Actor <?= e($row['actor_id']===null?'system':'#'.(string)$row['actor_id']) ?><?= !empty($row['ip'])?' · '.e($row['ip']):'' ?></small></div></article><?php endforeach; ?></div><?php endif; ?>
<?php if ($pages > 1): ?><nav class="pagination" aria-label="Audit pages"><?php for ($n=1;$n<=$pages;$n++): ?><a class="<?= $n===$page?'active':'' ?>" href="<?= e_attr($basePath) ?>/admin/audit?<?= e_attr(http_build_query(array_filter(['q'=>$search,'event'=>$eventPrefix,'page'=>$n]))) ?>"><?= $n ?></a><?php endfor; ?></nav><?php endif; ?>
</div>
